<template>
  <section class="panel fire-section" v-loading="f.recordsLoading">
    <form class="fire-record-filters" @submit.prevent="f.loadRecords(true)"><FireSectionFilter /><el-select v-model="f.recordQuery.areaId" clearable placeholder="全部区域" aria-label="记录区域"><el-option v-for="a in f.areas" :key="a.id" :label="a.name" :value="a.id" /></el-select><el-select v-model="f.recordQuery.result" clearable placeholder="全部结果" aria-label="点检结果"><el-option label="正常" value="normal" /><el-option label="异常" value="abnormal" /></el-select><el-input v-model="f.recordQuery.q" placeholder="器材编码、位置或点检人" aria-label="搜索点检记录" clearable /><el-date-picker v-model="f.recordDates" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /><div class="fire-record-actions"><el-button native-type="submit">查询</el-button><el-button :loading="f.exporting" @click="f.listAction('export')">导出记录</el-button></div></form>
    <el-alert v-if="f.recordsError" :title="f.recordsError" type="error" :closable="false" />
    <el-table :data="f.recordRows" empty-text="当前条件暂无点检记录"><el-table-column label="器材 / 点位" min-width="230"><template #default="{row}"><strong>{{ recordCodes(row) }}</strong><small class="table-secondary">{{ row.pointSnapshot?.sectionName || '未分工段' }} · {{ row.pointSnapshot?.areaName }} · {{ row.pointSnapshot?.location || row.pointSnapshot?.name || row.pointSnapshot?.code }}</small></template></el-table-column><el-table-column label="点检状态" width="110"><template #default><span class="point-state checked">已完成</span></template></el-table-column><el-table-column label="检查结果" width="110"><template #default="{row}"><el-tag :type="row.result==='normal'?'success':'danger'">{{ f.resultName(row.result) }}</el-tag></template></el-table-column><el-table-column prop="actorName" label="点检人" min-width="110" /><el-table-column label="点检时间" min-width="185"><template #default="{row}">{{ f.time(row.actualCheckedAt || row.submittedAt) }}<small v-if="row.source==='ai_photo' || row.recognition || row.pointSnapshot?.recognition" class="table-secondary">拍照登记时间（系统）</small></template></el-table-column><el-table-column label="凭证" width="100"><template #default="{row}">{{ row.photos?.length || 0 }} 张照片</template></el-table-column><el-table-column label="详情" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click="f.openRecord(row)">查看</el-button></template></el-table-column></el-table>
    <div v-if="f.recordTotal>f.recordQuery.pageSize" class="pagination-bar"><el-pagination v-model:current-page="f.recordQuery.page" :page-size="f.recordQuery.pageSize" :total="f.recordTotal" layout="total, prev, pager, next" @current-change="f.loadRecords()" /></div>
  </section>
</template>
<script setup>
import FireSectionFilter from './FireSectionFilter.vue'
import { inject } from 'vue'
const f=inject('fireInspection')
function recordCodes(record){return (record.items||[]).map(i=>i.assetSnapshot?.code||i.assetSnapshot?.name).filter(Boolean).join('、')||record.pointSnapshot?.code||'消防器材'}
</script>
